public void selectionSort(int[] arr) {
    for (int i = 0; i < arr.length - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < arr.length; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        int temp = arr[i];
        arr[i] = arr[minIndex];
        arr[minIndex] = temp;
    }
}

Java.Functions:
public void selectionSort(int[] arr) {
    for (int i = 0; i < arr.length - 1; i++) {
        int minIndex = findMinIndex(arr, i);
        swap(arr, i, minIndex);
    }
}

private int findMinIndex(int[] arr, int start) {
    int minIndex = start;
    for (int j = start + 1; j < arr.length; j++) {
        if (arr[j] < arr[minIndex]) {
            minIndex = j;
        }
    }
    return minIndex;
}

private void swap(int[] arr, int left, int right) {
    int temp = arr[left];
    arr[left] = arr[right];
    arr[right] = temp;
}

Java.Recursion:
public void selectionSortRecursive(int[] arr, int start) {
    if (start >= arr.length - 1) {
        return;
    }
    int minIndex = start;
    for (int j = start + 1; j < arr.length; j++) {
        if (arr[j] < arr[minIndex]) {
            minIndex = j;
        }
    }
    int temp = arr[start];
    arr[start] = arr[minIndex];
    arr[minIndex] = temp;
    selectionSortRecursive(arr, start + 1);
}

C.Iterative:
#include <stdio.h>

int main() {
    int n;

    // Step 1: Read how many elements are present.
    printf("Enter number of elements: ");
    scanf("%d", &n);

    // Step 2: Create an array to store the input values.
    int A[100];

    // Step 3: Read all elements into the array.
    printf("Enter elements:\n");
    for (int i = 1; i <= n; i++) {
        printf("Enter value: ");
        scanf("%d", &A[i]);
    }

    // Step 4: Run Selection Sort.
    // Each pass places the smallest remaining element in its correct position.
    for (int k = 1; k <= n - 1; k++) {
        // Assume the current position already has the minimum value.
        int min = A[k];
        int loc = k;

        // Search the remaining unsorted part for a smaller value.
        for (int j = k + 1; j <= n; j++) {
            if (min > A[j]) {
                min = A[j];
                loc = j;
            }
        }

        // Swap the found minimum value into position k.
        int temp = A[k];
        A[k] = A[loc];
        A[loc] = temp;
    }

    // Step 5: Print the sorted array.
    printf("Sorted array:\n");
    for (int i = 1; i <= n; i++) {
        printf("%d ", A[i]);
    }

    return 0;
}
